UPDATE t_workflow_definition SET definition_name = #{row.definitionName}, description = #{row.description},
        status = #{row.status}, current_version_no = #{row.currentVersionNo}, draft_version_no = #{row.draftVersionNo},
        version = version + 1, updated_by = #{row.updatedBy}, update_time = #{row.updateTime}
        WHERE definition_id = #{row.definitionId} AND version = #{row.version}
